viewnames={'keys','values','items'}
hits=set()
parse_fail=0
for e in d:
    p=e.get('program','') or ''
    try:
        t=ast.parse(p)
    except Exception:
        parse_fail+=1
        continue
    # track vars assigned a .keys()/.items()/.values() call
    viewvars=set()
    for n in ast.walk(t):
        if isinstance(n,ast.Assign) and isinstance(n.value,ast.Call) \
           and isinstance(n.value.func,ast.Attribute) and n.value.func.attr in viewnames \
           and not n.value.args:
            for tg in n.targets:
                if isinstance(tg,ast.Name): viewvars.add(tg.id)
    def isview(x):
        if isinstance(x,ast.Call) and isinstance(x.func,ast.Attribute) and x.func.attr in viewnames and not x.args:
            return True
        if isinstance(x,ast.Name) and x.id in viewvars: return True
        return False
    for n in ast.walk(t):
        if isinstance(n,ast.BinOp) and isinstance(n.op,(ast.BitOr,ast.BitAnd,ast.BitXor,ast.Sub)):
            if isview(n.left) or isview(n.right):
                hits.add(e.get('id'))
        if isinstance(n,ast.AugAssign) and isinstance(n.op,(ast.BitOr,ast.BitAnd,ast.BitXor,ast.Sub)):
            if isview(n.value): hits.add(e.get('id'))
