def sweep(exprs, label):
    diffs = []; refused = 0; errs = 0; ok = 0; rcdiff = []
    for e in exprs:
        prog = "print(repr(%s))" % e
        lrc, lo, le = run(LYP, prog)
        crc, co, ce = run(CPY, prog)
        if lrc == 90:
            refused += 1; continue
        if crc != 0:
            errs += 1
            if lrc == 0:
                rcdiff.append((e, "cpy_err rc=%d %s" % (crc, ce.strip().splitlines()[-1] if ce.strip() else ""), "lyp ok: "+lo.strip()))
            continue
        if lrc != 0:
            rcdiff.append((e, "lyp rc=%d" % lrc, le.strip()[-200:])); continue
        if lo != co:
            diffs.append((e, lo.strip(), co.strip()))
        else:
            ok += 1
    print("### %s: %d exprs, ok=%d refused=%d cpy_err=%d MISMATCH=%d rcdiff=%d" % (label, len(exprs), ok, refused, errs, len(diffs), len(rcdiff)))
    for e, l, c in diffs:
        print("  MISMATCH  %s\n     lyp: %s\n     cpy: %s" % (e, l, c))
    for e, a, b in rcdiff:
        print("  RCDIFF    %s\n     %s\n     %s" % (e, a, b))
    return diffs

import base64, binascii
STD="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
def described_decode(s, alphabet=STD):
    # "a 6-bit accumulator decode that skips '=' and newlines"
    acc=0; nbits=0; out=bytearray()
    for ch in s.decode('latin1'):
        if ch in '=\n\r': continue
        i=alphabet.find(ch)
        if i<0: continue   # lenient default: skip non-alphabet
        acc=(acc<<6)|i; nbits+=6
        if nbits>=8:
            nbits-=8; out.append((acc>>nbits)&0xFF)
    return bytes(out)

