                    out.push(b[i..].to_vec());
                    return out;
                }
                let start = i;
                while i < n && !py_byte_space(b[i]) {
                    i += 1;
                }
                out.push(b[start..i].to_vec());
                splits += 1;
                while i < n && py_byte_space(b[i]) {
                    i += 1;
                }
            }
