    let n = t.len();
    let mut chunks: Vec<Chunk> = Vec::new();
    let mut i = 0usize;
    while i < n {
        // `%(ws)s+`
        if ascii_space(t[i]) {
            let mut j = i;
            while j < n && ascii_space(t[j]) {
                j += 1;
            }
            chunks.push((i as u32, j as u32));
            i = j;
            continue;
        }
        // `(?<=%(wp)s) -{2,} (?=\\w)`
        if t[i] == '-' && i > 0 && is_wp(t[i - 1]) && em_dash_at(t, i) {
            let mut j = i;
            while j < n && t[j] == '-' {
                j += 1;
            }
            chunks.push((i as u32, j as u32));
            i = j;
            continue;
        }
        // The lazy `%(nws)s+?` grows `k` from 1. It may not cross whitespace,
        // so the second terminator fires at the first one and this loop always
        // ends — at `n` if the text runs out first.
        let mut k = 1usize;
        let end = loop {
            let p = i + k; // the position after the lazy part
            // `-(?:(?<=lt{2}-)|(?<=lt-lt-))(?=lt-?lt)` — the hyphen is
            // CONSUMED, so this chunk is `k + 1` characters long.
            if p < n && t[p] == '-' && hyphen_break(t, p) {
                break p + 1;
            }
            // `(?=%(ws)s|\\z)`
            if p == n || ascii_space(t[p]) {
                break p;
            }
            // `(?<=%(wp)s) (?=-{2,}\\w)`
            if t[p] == '-' && is_wp(t[p - 1]) && em_dash_at(t, p) {
                break p;
            }
            k += 1;
        };
        chunks.push((i as u32, end as u32));
        i = end;
    }
    chunks
}

