    t: &[char],
    chunks: &mut Vec<Chunk>,
    cur: &mut Vec<Chunk>,
    cur_len: usize,
    width: usize,
) {
    let space_left = width - cur_len;
    if space_left > 0 {
        let c = chunks.pop().expect("caller checked the stack is not empty");
        let mut end = space_left;
        if len(c) > space_left {
            // `chunk.rfind('-', 0, space_left)`: the last hyphen strictly
            // inside the part that would fit, and only when something that is
            // not a hyphen precedes it.
            let head = &t[c.0 as usize..c.0 as usize + space_left];
            if let Some(h) = head.iter().rposition(|x| *x == '-') {
                if h > 0 && head[..h].iter().any(|x| *x != '-') {
                    end = h + 1;
                }
            }
        }
        let cut = c.0 + end as u32;
        cur.push((c.0, cut));
        chunks.push((cut, c.1));
    } else if cur.is_empty() {
        cur.push(chunks.pop().expect("caller checked the stack is not empty"));
    }
}

