        kwargs.iter().map(|(k, v)| (k.as_ref(), v)).collect();
    for d in dstar {
        let Expr::Dict(pairs) = d else { return None };
        for (k, v) in pairs {
            match k {
                Expr::Str(s) => kws.push((s.as_ref(), v)),
                _ => return None,
            }
        }
    }
    Some((pos, kws))
