# back up over any doc comments/attrs preceding that fn
k=j+1
lines_before=s[:k].rstrip('\n').split('\n')
# find start of contiguous /// or #[ block above
m=len(lines_before)
while m>0 and (lines_before[m-1].startswith('///') or lines_before[m-1].startswith('#[')):
    m-=1
pos=len('\n'.join(lines_before[:m]))+1
s=s[:pos]+'\n'+helper+s[pos:].lstrip('\n')
