/// The one place `make_dir`'s two layers can disagree, and it is refused rather
/// than decided.
///
/// The existence test is [`path_exists`], which merges staging; the creation is
/// `std::fs::create_dir`, which can only ask the disk. A path this run has
/// staged a DELETE of is free to the first and taken by the second, so
/// `os.remove('F'); os.mkdir('F')` raised `FileExistsError` at exit 1 where
/// CPython removes the file and makes the directory at exit 0. Neither layer
/// can serve it alone: honouring staging needs the delete to have HAPPENED,
/// which the barrier will not do before a commit, and honouring the disk is a
/// wrong answer. So the engine refuses and CPython does both for real, one
/// spawn later.
///
/// The check costs an `exists()` only for a path the run has actually removed,
/// which is why it is here and not folded into `path_exists`.
fn staged_delete_blocks(path: &str) -> R<()> {
    if is_staged_deleted(path) && std::path::Path::new(path).exists() {
        return Err(unsupported(
            "mkdir",
            &format!(
                "mkdir('{path}') over a path this run removed but has not committed — the \\
                 staging layer says it is free and the disk says it is taken"
            ),
        ));
    }
    Ok(())
}""")

