def blocker_only_in_def(src, detail):
    tok=detail.strip().lstrip('.').rstrip('()').split()[-1].split('.')[-1]
    try: t=ast.parse(src)
    except SyntaxError: return None
    top=set(); indef=set()
    for n in ast.walk(t):
        pass
    # mark nodes inside any FunctionDef
    def collect(node, inside):
        for c in ast.iter_child_nodes(node):
            ins = inside or isinstance(c,(ast.FunctionDef,ast.AsyncFunctionDef))
            if isinstance(c,ast.Attribute): (indef if ins else top).add(c.attr)
            if isinstance(c,ast.Name): (indef if ins else top).add(c.id)
            if isinstance(c,(ast.Import,ast.ImportFrom)):
                ns=[a.name.split('.')[0] for a in c.names] if isinstance(c,ast.Import) else [(c.module or '').split('.')[0]]
                for m in ns: (indef if ins else top).add(m)
            collect(c, ins)
    collect(t, False)
    if tok in indef and tok not in top: return True
    return False
