p = pathlib.Path("textwrap.rs"); s = p.read_text()
old_start = s.index("fn wrap_chunks(mut chunks: Vec<Vec<char>>")
old_end = s.index("/// `str.rstrip()`")
new = '''fn wrap_chunks(t: &[char], mut chunks: Vec<Chunk>, width: usize, max_lines: Option<usize>) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    // CPython's two `ValueError`s — `invalid width` and `placeholder too large
    // for max width` — are decided by [`width_arg`] before any of this runs,
    // because both are properties of the width alone.
    chunks.reverse();
    while !chunks.is_empty() {
        let mut cur: Vec<Chunk> = Vec::new();
        let mut cur_len = 0usize;
        if !lines.is_empty() && strips_to_nothing(t, *chunks.last().expect("non-empty")) {
            chunks.pop();
        }
        while let Some(last) = chunks.last().copied() {
            if cur_len + len(last) > width {
                break;
            }
            cur_len += len(last);
            cur.push(last);
            chunks.pop();
        }
        if chunks.last().is_some_and(|c| len(*c) > width) {
            handle_long_word(t, &mut chunks, &mut cur, cur_len, width);
            cur_len = cur.iter().map(|c| len(*c)).sum();
        }
        if cur.last().is_some_and(|c| strips_to_nothing(t, *c)) {
            cur_len -= len(cur.pop().expect("just inspected"));
        }
        if cur.is_empty() {
            continue;
        }
        let fits = match max_lines {
            None => true,
            Some(m) => {
                lines.len() + 1 < m
                    || ((chunks.is_empty()
                        || (chunks.len() == 1 && strips_to_nothing(t, chunks[0])))
                        && cur_len <= width)
            }
        };
        if fits {
            lines.push(join(t, &cur));
            continue;
        }
        // The truncation branch. Every path out of it leaves the outer loop,
        // which is what CPython's two `break`s around the `while … else` do.
        let mut placed = false;
        while let Some(last) = cur.last().copied() {
            if !strips_to_nothing(t, last) && cur_len + PH.len() <= width {
                lines.push(join(t, &cur) + PH);
                placed = true;
                break;
            }
            cur_len -= len(last);
            cur.pop();
        }
        if !placed {
            // CPython's `while … else`: no chunk of this line survived, so the
            // placeholder goes onto the PREVIOUS line if it fits there, and
            // otherwise onto a line of its own.
            let onto = lines.last().map(|p| rstrip(p)).filter(|p| p.chars().count() + PH.len() <= width);
            match onto {
                Some(prev) => *lines.last_mut().expect("filtered from Some above") = prev + PH,
                None => lines.push(PH_LSTRIP.to_string()),
            }
        }
        break;
    }
    lines
}

'''
s = s[:old_start] + new + s[old_end:]

s = s.replace('''fn wrap_text(text: &str, width: usize, max_lines: Option<usize>) -> Vec<String> {
