import enum_shapes as E

CPY = "/opt/homebrew/Cellar/python@3.14/3.14.5/Frameworks/Python.framework/Versions/3.14/bin/python3.14"

PROBES = {
    # type_name reaching stdout at exit 0 through a TypeError the program catches
    "len": "try:\n    len(F)\nexcept TypeError as e:\n    print('T:', e)\n",
    # the SECOND call site: AttributeError text
    "attr": "try:\n    F.zznosuch\nexcept AttributeError as e:\n    print('A:', e)\n",
}

def program(setup, expr, probe):
    head = setup + "\n" if setup else ""
    return head + PROBES[probe].replace("F", expr)

def run(binary, prog):
    with tempfile.TemporaryDirectory() as d:
        try:
            p = subprocess.run([binary, "-c", prog], capture_output=True, text=True,
                               cwd=d, timeout=60,
                               env=dict(os.environ, LYPNING_CAPTURE="0"))
        except subprocess.TimeoutExpired:
            return (124, "", "timeout")
        return (p.returncode, p.stdout, p.stderr)

def main(engines):
    out = []
    for group, setup, expr in E.ROWS:
        for probe in PROBES:
            prog = program(setup, expr, probe)
            ref = run(CPY, prog)
            row = {"group": group, "expr": expr, "probe": probe,
                   "ref_rc": ref[0], "ref_out": ref[1]}
            for name, b in engines:
                rc, so, se = run(b, prog)
                row[name] = {"rc": rc, "out": so, "err": se.strip()[:200]}
            out.append(row)
    print(json.dumps(out))

if __name__ == "__main__":
