def snapshot(root):
    out = []
    for dp, dn, fn in os.walk(root):
        rel = os.path.relpath(dp, root)
        for d in sorted(dn): out.append("d " + os.path.normpath(os.path.join(rel, d)))
        for f in sorted(fn):
            p = os.path.join(dp, f)
            try: c = open(p,'rb').read()
            except Exception: c = b'?'
            out.append("f " + os.path.normpath(os.path.join(rel, f)) + " " + repr(c))
    return sorted(out)

def setup(root, pre):
    # pre: list of ops
    for op in pre:
        kind, arg = op[0], op[1:]
        if kind == 'd': os.makedirs(os.path.join(root, arg[0]), exist_ok=True)
        elif kind == 'f':
            p = os.path.join(root, arg[0])
            os.makedirs(os.path.dirname(p) or root, exist_ok=True)
            open(p,'wb').write(arg[1] if len(arg)>1 else b'x')
        elif kind == 'l': os.symlink(arg[1], os.path.join(root, arg[0]))

def run(cmd, prog, pre):
    root = tempfile.mkdtemp(prefix="lypattack-")
    setup(root, pre)
    before = snapshot(root)
    r = subprocess.run(cmd + ["-c", prog], cwd=root, capture_output=True)
    after = snapshot(root)
    res = dict(rc=r.returncode, out=r.stdout.decode('utf8','replace'),
               err=r.stderr.decode('utf8','replace'), fs=after, delta=[x for x in after if x not in before])
    shutil.rmtree(root, ignore_errors=True)
    return res

