for e in sel:
    try: t = ast.parse(e.program)
    except SyntaxError: continue
    binds = {}
    for n in ast.walk(t):
        if isinstance(n, ast.Assign):
            for tg in n.targets:
                if isinstance(tg, ast.Name):
                    binds.setdefault(tg.id, []).append(n.value.value if isinstance(n.value, ast.Constant) and isinstance(n.value.value,(str,bytes)) else None)
        for tg in ([n.target] if isinstance(n,(ast.For,ast.AugAssign,ast.NamedExpr)) else []):
            if isinstance(tg, ast.Name): binds.setdefault(tg.id, []).append(None)
        if isinstance(n, ast.comprehension) and isinstance(n.target, ast.Name): binds.setdefault(n.target.id, []).append(None)
    for n in ast.walk(t):
        if isinstance(n, ast.Call):
            f = n.func; nm=None
            if isinstance(f, ast.Attribute) and isinstance(f.value, ast.Name) and f.value.id=="re" and f.attr in FN: nm=f.attr
