"""Differential runner: <bin> -c P  vs  python3 -c P, per-engine temp cwd."""
from __future__ import annotations
import os, re, subprocess, sys, tempfile, shutil, json, pathlib

sys.path.insert(0, "/Users/user/dev/lypning-perf-io/src")
from lypning.conformance import stderr_shape  # noqa

UNSUP = re.compile(r"^[A-Za-z0-9_.-]+: unsupported: [^:]+: .+$")

def run(cmd, prog, tag):
    d = tempfile.mkdtemp(prefix="dc-%s-" % tag)
    try:
        p = subprocess.run(cmd + ["-c", prog], cwd=d, capture_output=True,
                           timeout=10, env=dict(os.environ, PYTHONIOENCODING="utf-8"))
        return p.returncode, p.stdout, p.stderr, False
    except subprocess.TimeoutExpired:
        return None, b"", b"", True
    finally:
        shutil.rmtree(d, ignore_errors=True)

def classify(prog, binpath):
    lrc, lout, lerr, lhang = run([binpath], prog, "l")
    crc, cout, cerr, chang = run(["/opt/homebrew/bin/python3"], prog, "c")
    if lhang:
        return "HANG", dict(prog=prog)
    if chang:
        return "SKIP-cpython-hang", dict(prog=prog)
    if lrc == 90:
        head = lerr.decode("utf-8", "replace").split("\n", 1)[0]
        rest = lerr.decode("utf-8", "replace").split("\n")[1:]
        bad = []
        if lout:
            bad.append("stdout non-empty on 90: %r" % lout[:200])
        if not UNSUP.match(head):
            bad.append("refusal head malformed: %r" % head)
        if any(x.strip() for x in rest):
            bad.append("extra stderr lines after refusal: %r" % rest)
        if bad:
            return "BAD-REFUSAL", dict(prog=prog, why="; ".join(bad),
                                       lrc=lrc, lout=lout.decode("u8","replace") if False else lout.decode("utf-8","replace"),
                                       lerr=lerr.decode("utf-8","replace"),
                                       crc=crc, cout=cout.decode("utf-8","replace"))
        return "UNSUPPORTED", dict(prog=prog)
    ok_out = (lout == cout)
    ok_rc = (lrc == crc)
    lpre, lexc = stderr_shape(lerr.decode("utf-8", "replace"))
    cpre, cexc = stderr_shape(cerr.decode("utf-8", "replace"))
    ok_err = (lpre == cpre and lexc == cexc)
    if ok_out and ok_rc and ok_err:
        return "MATCH", dict(prog=prog)
    kind = []
    if not ok_out: kind.append("stdout")
    if not ok_rc: kind.append("rc")
    if not ok_err: kind.append("stderr")
    return "MISMATCH", dict(prog=prog, kind=",".join(kind), lrc=lrc, crc=crc,
                            lout=lout.decode("utf-8","replace"), cout=cout.decode("utf-8","replace"),
                            lerr=lerr.decode("utf-8","replace"), cerr=cerr.decode("utf-8","replace"))

def main():
    binpath = sys.argv[1]
    progs = [l for l in pathlib.Path(sys.argv[2]).read_text().split("\n\x00\n") if l.strip()]
    counts = {}
    bad = []
    for p in progs:
        v, info = classify(p, binpath)
        counts[v] = counts.get(v, 0) + 1
        if v in ("MISMATCH", "BAD-REFUSAL", "HANG"):
            bad.append((v, info))
    print("bin:", binpath, "programs:", len(progs))
    print(json.dumps(counts, indent=0))
    for v, info in bad:
        print("=" * 60)
        print(v, "::", info["prog"])
        for k in ("kind", "why", "lrc", "crc", "lout", "cout", "lerr", "cerr"):
            if k in info:
                print("  %s: %r" % (k, info[k]))
    print("BADCOUNT", len(bad))

main()

