def sim(shared_cases, kc):
    rng=random.Random(7); win=0
    for _ in range(T):
        if shared_cases:
            idx=[rng.randrange(len(P)) for _ in range(n)]
            ps=[P[i] for i in idx]
            base=[1.0 if rng.random()<p else 0.0 for p in ps]              # same cases
            cand=[sum(1.0 if rng.random()<p else 0.0 for _ in range(kc))/kc for p in ps]
        else:
            pb=[P[rng.randrange(len(P))] for _ in range(n)]
            pc2=[P[rng.randrange(len(P))] for _ in range(n)]               # different cases
            base=[1.0 if rng.random()<p else 0.0 for p in pb]
            cand=[sum(1.0 if rng.random()<p else 0.0 for _ in range(kc))/kc for p in pc2]
        s=stats.summarize(cand, resamples=R, seed=rng.randrange(1<<30))
