    if !req.imports.contains("glob") {
        return false;
    }
    let Expr::Name(base) = b else { return false };
    let m = req
        .aliases
        .iter()
        .find(|(a, _)| a == base.as_ref())
        .map(|(_, p)| p.as_str())
        .unwrap_or(base.as_ref());
