        try:
            o.append("t")
            continue
        except Exception:
            o.append("x")
        else:
            o.append("e")
    return o
def a3():
    o = []
    def f():
        try:
            o.append("t")
            return "r"
        except Exception:
            o.append("x")
        else:
            o.append("e")
