import json, sys, subprocess, os
from concurrent.futures import ThreadPoolExecutor
ENG = sys.argv[1]; progs = json.load(open(sys.argv[2])); dst = sys.argv[3]

def wrap(src):
    body = "\n".join("    " + ln for ln in src.split("\n"))
    return ("try:\n" + body + "\nexcept BaseException as e:\n"
            "    print(type(e).__name__ + ' | ' + str(e))\n")

def run(src):
    try:
        r = subprocess.run([ENG, "-c", wrap(src)], capture_output=True, text=True, timeout=20)
    except subprocess.TimeoutExpired:
        return "TIMEOUT"
    if r.returncode == 90:
        return "REFUSED:" + r.stderr.strip()
    if r.returncode != 0:
        return "EXIT%d:%s" % (r.returncode, r.stderr.strip().splitlines()[-1] if r.stderr.strip() else "")
    s = r.stdout
    lines = [l for l in s.split("\n") if l]
    if not lines:
        return "OK"
    last = lines[-1]
    return last if " | " in last else "OK"

with ThreadPoolExecutor(max_workers=16) as ex:
    res = list(ex.map(run, progs))
json.dump(res, open(dst, "w"))

