ed('ops.rs','''    pub fn binop(&mut self, op: BinOp, a: &Value, b: &Value) -> R<Value> {
        use BinOp::*;''','''    pub fn binop(&mut self, op: BinOp, a: &Value, b: &Value) -> R<Value> {
        use BinOp::*;
        // `glob.glob(x) + glob.glob(y)` is the shape the corpus uses to search
        // two roots at once, and the CONCATENATION of two order-blind results
        // is order-blind too — so it stays one. Every other operator, and
        // every other partner, would read the order (`g * 2`, `g + [x]`,
        // `[x] + g` all place elements by position) and refuses.
        #[cfg(feature = "cap-glob")]
        match (a, b) {
            (Value::Glob(x), Value::Glob(y)) if matches!(op, Add) => {
                let mut items = crate::glob::items(x);
                items.extend(crate::glob::items(y));
