        // repr to 50 CHARACTERS and drops the closing quote when it does;
        // `re.compile('…')` does the same at 200 and renders its flags. Two
        // exact rules, neither of them worth guessing at: refused.
        #[cfg(feature = "cap-re")]
        Value::Pattern(_) | Value::Match(_) => {
            return Err(crate::re::refuse(&format!(
                "repr() of a {}, whose CPython repr truncates to a fixed width",
                type_name(v)
            )))
        }""", """        // `<re.Match object; span=(0, 2), match='ab'>` and
        // `re.compile('a', re.IGNORECASE)`. Both truncate — to 50 and 200
        // CHARACTERS of the inner repr, closing quote and all — and `re.rs`
        // has the rules; this arm is where `print(m)`, `str(p)` and `'%s' % m`
        // all arrive.
        #[cfg(feature = "cap-re")]
        Value::Pattern(_) | Value::Match(_) => return crate::re::repr(v),""")
