    // `0` never applies to a string conversion: `'%05s' % 'a'` is `'    a'`.
    if flags.contains('0') && !left && ty != "s" && ty != "r" {
        spec.push('0');
    }
    spec.push_str(width);
    spec.push_str(prec);
    if bare_dot {
        spec.push('0');
    }
    spec.push_str(ty);
