/// One numeric argument as f64, the way CPython's math module coerces.
fn mnum(args: &Args, name: &str) -> R<f64> {
    match args.first() {
        Some(Value::Float(f)) => Ok(*f),
        Some(Value::Int(i)) => Ok(*i as f64),
        Some(Value::Bool(b)) => Ok(*b as i64 as f64),
        Some(other) => Err(type_err(format!(
            "must be real number, not {}",
            type_name(other)
        ))),
        None => Err(type_err(format!("{name}() takes exactly one argument (0 given)"))),
    }
}

fn mint(v: Option<&Value>, name: &str) -> R<i64> {
    match v {
        Some(Value::Int(i)) => Ok(*i),
        Some(Value::Bool(b)) => Ok(*b as i64),
        Some(other) => Err(type_err(format!(
            "'{}' object cannot be interpreted as an integer",
            type_name(other)
        ))),
        None => Err(type_err(format!("{name}() missing required argument"))),
    }
}

fn math_call(name: &str, args: Args) -> R<Value> {
    Ok(match name {
        "sqrt" => {
            let x = mnum(&args, name)?;
            if x < 0.0 {
                return Err(value_err("math domain error"));
            }
            Value::Float(x.sqrt())
        }
        "log10" => {
            let x = mnum(&args, name)?;
            if x <= 0.0 {
                return Err(value_err("math domain error"));
            }
            Value::Float(x.log10())
        }
        "fabs" => Value::Float(mnum(&args, name)?.abs()),
        "isnan" => Value::Bool(mnum(&args, name)?.is_nan()),
        "isinf" => Value::Bool(mnum(&args, name)?.is_infinite()),
        "isfinite" => Value::Bool(mnum(&args, name)?.is_finite()),
        "floor" | "ceil" | "trunc" => match args.first() {
            Some(Value::Int(i)) => Value::Int(*i),
            Some(Value::Bool(b)) => Value::Int(*b as i64),
            _ => {
                let x = mnum(&args, name)?;
                let r = match name {
                    "floor" => x.floor(),
                    "ceil" => x.ceil(),
                    _ => x.trunc(),
                };
                Value::Int(crate::builtins::float_to_int(r, name)?)
            }
        },
        "gcd" => {
            let mut g: i64 = 0;
            for (i, _) in args.iter().enumerate() {
                let v = mint(args.get(i), name)?;
                let mut a = g.unsigned_abs();
                let mut b = v.unsigned_abs();
                while b != 0 {
                    let t = a % b;
                    a = b;
                    b = t;
                }
                if a > i64::MAX as u64 {
                    return Err(unsupported("bigint", "math.gcd() beyond 64-bit range"));
                }
                g = a as i64;
            }
            Value::Int(g)
        }
        "factorial" => {
            let n = mint(args.first(), name)?;
            if n < 0 {
                return Err(value_err("factorial() not defined for negative values"));
            }
            let mut acc: i64 = 1;
            for k in 2..=n {
                acc = match acc.checked_mul(k) {
                    Some(v) => v,
                    None => {
                        return Err(unsupported(
                            "bigint",
                            "math.factorial() beyond 64-bit range (Python would use a bignum)",
                        ))
                    }
                };
            }
            Value::Int(acc)
        }
        _ => return Err(unsupported("module-attr", &format!("math.{name}()"))),
    })
}
