def boolish(n):
    if isinstance(n, ast.Constant) and isinstance(n.value, bool): return True
    if isinstance(n, ast.Compare): return True
    if isinstance(n, ast.UnaryOp) and isinstance(n.op, ast.Not): return True
    if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in ('bool','isinstance','callable','any','all','hasattr'): return True
    if isinstance(n, ast.BinOp) and isinstance(n.op, BITOPS): return boolish(n.left) and boolish(n.right)
    return False

