"""Differential runner: <engine> -c P vs python3 -c P, per-engine temp cwd."""
from __future__ import annotations
import os, re, subprocess, sys, tempfile, shutil, json

ENGINES = {
    "lypning": "/tmp/lyp-cap-repr/bin/lypning",
    "lypning-l": "/tmp/lyp-cap-repr/bin/lypning-l",
}
PARENT = {
    "lypning": "/tmp/lyp-advA-parent-home/bin/lypning",
    "lypning-l": "/tmp/lyp-advA-parent-home/bin/lypning-l",
}

def run(cmd, cwd, prog):
    try:
        p = subprocess.run(cmd + ["-c", prog], cwd=cwd, capture_output=True, timeout=10)
        return p.returncode, p.stdout, p.stderr, False
    except subprocess.TimeoutExpired:
        return None, b"", b"", True

REF = re.compile(rb"^[a-z0-9\-]+: unsupported: [^:]+: .*\n$")

def classify(prog, name, binp, refrc, refout, referr, reftimeout):
    d = tempfile.mkdtemp(prefix="lypdiff-%s-" % name)
    try:
        rc, out, err, hung = run([binp], d, prog)
    finally:
        shutil.rmtree(d, ignore_errors=True)
    if hung:
        return "HANG", (rc, out, err)
    if rc == 90:
        problems = []
        if out != b"":
            problems.append("stdout non-empty on exit 90: %r" % out[:200])
        lines = err.splitlines(True)
        if len(lines) != 1 or not REF.match(err):
            problems.append("bad refusal line: %r" % err[:300])
        if problems:
            return "BADREFUSAL:" + "; ".join(problems), (rc, out, err)
        return "REFUSED", (rc, out, err)
    if reftimeout:
        return "REF_TIMEOUT", (rc, out, err)
    if (rc, out, err) == (refrc, refout, referr):
        return "MATCH", (rc, out, err)
    # differentiate
    tag = []
    if out != refout:
        tag.append("stdout")
    if err != referr:
        tag.append("stderr")
    if rc != refrc:
        tag.append("rc")
    return "DIFF(" + ",".join(tag) + ")", (rc, out, err)

def main(path):
    progs = [l.rstrip("\n") for l in open(path) if l.strip() and not l.startswith("#@")]
    results = []
    for prog in progs:
        d = tempfile.mkdtemp(prefix="lypdiff-cpy-")
        try:
            rrc, rout, rerr, rhung = run([sys.executable], d, prog)
        finally:
            shutil.rmtree(d, ignore_errors=True)
        row = {"prog": prog, "cpython": (rrc, rout.decode("utf8","replace"), rerr.decode("utf8","replace")), "hung": rhung}
        for name, binp in ENGINES.items():
            v, got = classify(prog, name, binp, rrc, rout, rerr, rhung)
            row[name] = v
            row[name + "_got"] = (got[0], got[1].decode("utf8","replace"), got[2].decode("utf8","replace"))
        results.append(row)
    bad = [r for r in results if any(not str(r[n]).startswith(("MATCH","REFUSED")) for n in ENGINES)]
    print("total %d  bad %d" % (len(results), len(bad)))
    for r in bad:
        print("=" * 70)
        print("PROG: " + r["prog"])
        print("  cpython rc=%s out=%r err=%r" % (r["cpython"][0], r["cpython"][1][:300], r["cpython"][2][:300]))
        for n in ENGINES:
            print("  %-10s %s rc=%s out=%r err=%r" % (n, r[n], r[n+"_got"][0], r[n+"_got"][1][:300], r[n+"_got"][2][:300]))
    json.dump([{k: v for k, v in r.items()} for r in results], open(path + ".json", "w"), default=str)
    # summary counts
    for n in ENGINES:
        from collections import Counter
        print(n, Counter(str(r[n]).split("(")[0].split(":")[0] for r in results))

main(sys.argv[1])

