VALS=["2","2.5","True","'ab'","b'ab'","[1]","(1,)","{'a':1}","{1}","None","-0.0","0"]
cases=[]
for a in VALS:
    for b in VALS:
        for op in OPS:
            cases.append(("%s %s %s"%(a,op,b), "try: print(repr(%s %s %s))\nexcept Exception as e: print('E')" % (a,op,b)))
        cases.append(("%s in %s"%(a,b), "try: print(repr(%s in %s))\nexcept Exception as e: print('E')" % (a,b)))
for a in VALS:
    for u in ["-","+"]:
        cases.append(("%s%s"%(u,a), "try: print(repr(%s%s))\nexcept Exception as e: print('E')" % (u,a)))
diff=ref=0; ex=[]
for name,prog in cases:
    r=subprocess.run([LYP,'-c',prog],capture_output=True,text=True)
    if r.returncode==90: ref+=1; continue
    c=subprocess.run([CPY,'-c',prog],capture_output=True,text=True)
    if (r.stdout,r.returncode)!=(c.stdout,c.returncode):
        diff+=1; ex.append((name,r.stdout.strip()[:24],c.stdout.strip()[:24]))
print("cells=%d ran=%d refused=%d differ=%d" % (len(cases), len(cases)-ref, ref, diff))
for n,x,y in ex: print("  %-22s lyp=%-14s cpy=%s" % (n,x,y))

