import json, ast, re
data = json.load(open('/home/user/lypning/.hillclimb/corpus.json'))

def is_floatish(n):
    if isinstance(n, ast.Constant) and isinstance(n.value,float): return True
    if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='float': return True
    return False

cands=[]
for e in data:
    src=e.get('program','') or ''
    try: tree=ast.parse(src)
    except Exception: continue
    for n in ast.walk(tree):
        if isinstance(n, ast.Compare):
            ops=[n.left]+list(n.comparators)
            if any(is_floatish(o) for o in ops) and not all(is_floatish(o) for o in ops):
                cands.append((e.get('id'), src[:200]))
                break
print("comparisons mixing a float literal/float() with a non-float operand:", len(cands))
