"""Differential harness: engine vs CPython, per-engine temp cwd."""
from __future__ import annotations
import os, subprocess, sys, tempfile, json

BIN = {
    "lypning": "/tmp/lyp-adv2-glob/bin/lypning",
    "lypning-l": "/tmp/lyp-adv2-glob/bin/lypning-l",
}
CPY = sys.executable

DIRS = ["d", "d/sub", "e"]
FILES = ["a.py", "b.py", "c.txt", ".hidden", "d/x.py", "d/y.txt", "d/sub/z.py", "e/.dot"]
LINKS = [("broken", "nowhere"), ("link.py", "a.py")]

def tree(root):
    for x in DIRS:
        os.makedirs(os.path.join(root, x), exist_ok=True)
    for f in FILES:
        p = os.path.join(root, f)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        open(p, "w").close()
    for n, t in LINKS:
        try:
            os.symlink(t, os.path.join(root, n))
        except FileExistsError:
            pass

def snapshot(root):
    out = []
    for dp, dn, fn in os.walk(root):
        for x in list(dn) + list(fn):
            out.append(os.path.relpath(os.path.join(dp, x), root))
    return sorted(out)

def run(argv, program, mktree=True):
    with tempfile.TemporaryDirectory() as d:
        if mktree:
            tree(d)
        before = snapshot(d)
        try:
            p = subprocess.run(argv + ["-c", program], capture_output=True, text=True,
                               cwd=d, timeout=20)
            rc, so, se = p.returncode, p.stdout, p.stderr
        except subprocess.TimeoutExpired:
            rc, so, se = "TIMEOUT", "", ""
        after = snapshot(d)
        return rc, so, se, sorted(set(after) - set(before)), sorted(set(before) - set(after))

def refusal_problem(engine, rc, so, se):
    if rc != 90:
        return "exit %s, not 90" % rc
    if so != "":
        return "stdout not empty: %r" % so[:200]
    line = se.strip()
    head = "%s: unsupported: " % engine
    if not line.startswith(head) or "\n" in line:
        return "stderr %r, expected one %r line" % (line[:200], head)
    return None

def check(program, engines=("lypning", "lypning-l"), mktree=True, verbose=False):
    """Return list of problem strings."""
    problems = []
    rrc, rso, rse, radd, rdel = run([CPY], program, mktree)
    for e in engines:
        rc, so, se, add, dele = run([BIN[e]], program, mktree)
        if rc == 90:
            p = refusal_problem(e, rc, so, se)
            if p:
                problems.append((e, "BADREFUSAL: " + p, program, rc, so, se))
            elif add or dele:
                problems.append((e, "REFUSAL-WITH-WRITES: added=%r removed=%r" % (add, dele), program, rc, so, se))
            continue
        if (so, rc) != (rso, rrc):
            problems.append((e, "DISAGREE: cpython=(%r,%s) engine=(%r,%s) stderr=%r" % (rso, rrc, so, rc, se.strip()[-200:]), program, rc, so, se))
        if rc not in (0, 1) and rc != rrc:
            problems.append((e, "ODDEXIT %s" % rc, program, rc, so, se))
    return problems

def route(engine, program):
    p = subprocess.run([BIN[engine], "route", "-c", program], capture_output=True, text=True, timeout=20)
    return p.stdout.strip(), p.stderr.strip(), p.returncode

