L="/root/.lypning/bin/lypning"; C="/usr/bin/python3"
# Skip exactly the two divergent sets (computed here from CPython), then diff the rest.
SKIP = r"""
def cf_bad(ch):
    return ch.casefold() != ch.lower()
def ti_bad(ch):
    return ch.title() != ch.upper()
out = []
for c in range(0x110000):
    if 0xD800 <= c <= 0xDFFF:
        continue
    ch = chr(c)
    if %s:
        continue
    r = ch.%s()
    if r != ch:
        out.append(str(c) + ':' + ','.join(str(ord(x)) for x in r))
print(len(out))
print(' '.join(out))
"""
for meth, guard in [("casefold","cf_bad(ch)"), ("title","ti_bad(ch)"), ("capitalize","ti_bad(ch)")]:
    prog = SKIP % (guard, meth)
    a=subprocess.run([L,"-c",prog],capture_output=True,text=True)
    b=subprocess.run([C,"-c",prog],capture_output=True,text=True)
    if a.returncode==90:
        print("%-11s STILL REFUSES inside the allowed set: %s" % (meth, a.stderr.strip()[:70])); continue
    A=dict(x.split(':') for x in a.stdout.split('\n')[1].split()) if a.stdout.strip() else {}
    B=dict(x.split(':') for x in b.stdout.split('\n')[1].split()) if b.stdout.strip() else {}
    diffs=sorted((set(A)|set(B)), key=int)
    diffs=[k for k in diffs if A.get(k)!=B.get(k)]
    print("%-11s %d differing codepoints outside the refused set" % (meth,len(diffs)))
    for k in diffs[:6]:
        f=lambda v: ''.join(chr(int(x)) for x in v.split(',')) if v else '(unchanged)'
        print("    U+%04X -> lyp %r cpy %r" % (int(k), f(A.get(k)), f(B.get(k))))

