    W("\n  BEST-OF-2, %d programs:\n" % len(clean))
    ref = best["cold-cpython"]
    for k, v in sorted(best.items(), key=lambda kv: kv[1]):
        W("    %-26s %8.0f ms  %6.2f ms/prog  %5.2fx vs cold CPython\n"
