    for tag in ("skipped_abspath", "retained"):
        s = out["exclusion_bias"][tag]
        W("  %-18s n=%4d  open sites/program %.3f  features %s\n"
          % (tag, s["n"], s["open_sites_per_program"], s["features_pct"]))

