        if not self_host:
            counts["no-self"][v] += 1
    out["self_hosting"] = {k: dict(v) for k, v in counts.items()}
    for tag in ("all", "no-self"):
        c = counts[tag]
        tot = sum(c.values()) or 1
        W("  %-8s n=%4d  match %4d (%.1f%%)  refused %4d  silent-diff %d\n"
