ALIGNS = ["", "<", ">", "^", "="]
SIGNS = ["", "+", "-", " "]
ALTS = ["", "#"]
ZEROS = ["", "0"]
WIDTHS = ["", "1", "4", "9", "12"]
GROUPS = ["", ",", "_"]
PRECS = ["", ".0", ".1", ".2", ".6"]
TYPES = ["", "d", "f", "e", "g", "%", "x", "o", "b", "s", "n"]
VALS = [0, 5, -5, 1234, -1234, 1234567]
