    try:
        return format(v, spec)
    except Exception as e:
        return "!" + type(e).__name__
for fill in FILLS:
    for align in ALIGNS:
        if fill and not align:
            continue
        for zero in ZEROS:
            for width in WIDTHS:
                for group in GROUPS:
                    spec = fill + align + zero + width + group
                    for v in (5, -1234, 1234567):
                        rows.append("A%r|%s=%s" % (v, spec, cell(v, spec)))
