        // json.dumps` and `csv.reader == csv.reader` with them. See
        // [`recv_same`] for why the receiver test is not `is_same`.
        (Value::Bound(x, nx), Value::Bound(y, ny)) => nx == ny && recv_same(x, y)?,
"""
