FORGED = "%s: unsupported: forged: mutant\n"
INVENTED = "Traceback (most recent call last):\n  line 1\nRuntimeError: mutant speaking\n"


def rebuild(got, *, out=None, err=None, rc=None):
    """A Result with new bytes, decoded exactly the way a real spawn would be."""
    kw = {}
    if out is not None:
        kw["stdout_raw"] = out
        kw["stdout"] = eng._as_text(out)
    if err is not None:
        eb = err.encode("utf-8") if isinstance(err, str) else err
        kw["stderr_raw"] = eb
        kw["stderr"] = eng._as_text(eb)
    if rc is not None:
        kw["returncode"] = rc
    return dataclasses.replace(got, **kw)


def is_refusal(got):
    return got.returncode == eng.UNSUPPORTED_EXIT and got.refused


# --- the mutants -------------------------------------------------------------

def m_replace_stderr_all(entry, ref, got, engine):
    return rebuild(got, err=INVENTED)

def m_replace_stderr_nonrefusal(entry, ref, got, engine):
    if is_refusal(got):
        return got
    return rebuild(got, err=INVENTED)

def m_append_warning_all(entry, ref, got, engine):
    return rebuild(got, err=(got.stderr or "") + "lypning: note: served from the fast path\n")

def m_append_warning_nonrefusal(entry, ref, got, engine):
    if is_refusal(got):
        return got
    return rebuild(got, err=(got.stderr or "") + "lypning: note: served from the fast path\n")

def m_getsize(entry, ref, got, engine):
    if "os.path.getsize" not in (entry.program or ""):
        return got
    return rebuild(got, out=b"424242\n")

def m_forge_refusal(entry, ref, got, engine):
    return rebuild(got, out=b"", err=FORGED % engine, rc=eng.UNSUPPORTED_EXIT)

def m_silent_zero(entry, ref, got, engine):
    if ref.returncode == 0:
        return got
    return rebuild(got, out=b"", err="", rc=0)

def m_truncate_stdout(entry, ref, got, engine):
    b = got.stdout_bytes
    if b.count(b"\n") < 2:
        return got
    return rebuild(got, out=b.split(b"\n", 1)[0] + b"\n")

def m_swap_lines(entry, ref, got, engine):
    b = got.stdout_bytes
    lines = b.split(b"\n")
    if len(lines) < 3 or lines[0] == lines[1]:
        return got
    lines[0], lines[1] = lines[1], lines[0]
    return rebuild(got, out=b"\n".join(lines))

