import base64, random
A=b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
def hyp(s):
    data=bytes(c for c in s if c in A)
    n=len(data); qp=n%4
    last=-1
    for i,c in enumerate(s):
        if c in A: last=i
    pads=sum(1 for c in s[last+1:] if c==0x3d)
    if qp==1: return 'ERR'
    if qp and pads < 4-qp: return 'ERR'
    out=bytearray(); acc=0; nb=0
    for c in data:
        acc=(acc<<6)|A.index(c); nb+=6
        if nb>=8: nb-=8; out.append((acc>>nb)&0xFF)
    return bytes(out)
random.seed(1234)
pool = b'ABCXYZabcxyz019+/=-_ \n\t!\x00\xff==='
bad=0; total=0
for _ in range(150000):
    n = random.randint(0, 26)
    s = bytes(random.choice(pool) for _ in range(n))
    total+=1
    try: cp = base64.b64decode(s)
    except Exception: cp = 'ERR'
    h = hyp(s)
    if cp != h:
        bad+=1
        if bad<8: print('DIFF %r cpy=%r hyp=%r' % (s, cp, h))
print('checked', total, 'divergences', bad)

