start = s.index('/// The read half of `FileObj::csv_consumed`: every path that would observe the')
end = s.index('pub fn file_write(f: &FileObj, bytes: &[u8]) -> R<usize> {')
new_guards = '''/// Every path this run has staged a write to, and how many times.
