///
/// One pass rather than two because the two disagree about only one thing and
/// it is easy to state: `expandtabs` resets the column at `\\n` and `\\r` and at
/// nothing else, so `\\v` and `\\f` advance it by one before the translation
/// turns them into spaces. `str.expandtabs` is in `methods::STR_MISSING`, so
/// this is the only implementation of it in the tree and it is deliberately
/// private — it is half of `_munge_whitespace`, not a method this engine now
/// has. A `\\u{a0}` survives untouched and is a word character to [`split`],
/// which is the half CPython hardcodes.
fn munge(s: &str) -> Vec<char> {
    let mut out: Vec<char> = Vec::with_capacity(s.len());
    let mut col = 0usize;
    for c in s.chars() {
        match c {
            '\\t' => {
                let incr = 8 - (col % 8);
                col += incr;
                for _ in 0..incr {
                    out.push(' ');
                }
            }
            '\\n' | '\\r' => {
                out.push(' ');
                col = 0;
            }
            c => {
                out.push(if ascii_space(c) { ' ' } else { c });
                col += 1;
            }
        }
    }
    out
}

