test("mergeSightings: a hand-applied tag survives the rebuild", () => {
  const tagged = {
    id: "t", program: "print(1)", argv_tail: [], source: "shim",
    first_seen: "2026-01-01T00:00:00Z", count: 2, stdin_sample: null,
