def sha(b): return hashlib.sha256(b if isinstance(b,bytes) else b.encode()).hexdigest()
def run(binary,prog,n=1):
    outs=[]
    for _ in range(n):
        d=tempfile.mkdtemp()
        for k,v in (T.get('files') or {}).items():
            open(os.path.join(d,k),'wb').write(v.encode('latin-1') if any(ord(c)>127 for c in v) else v.encode())
        open(os.path.join(d,'s.py'),'w').write(prog)
        p=subprocess.run([binary,'s.py']+[str(a) for a in (T.get('argv') or [])],cwd=d,
                         input=T.get('stdin'),capture_output=True,text=True,timeout=30)
        outs.append((p.returncode,p.stdout,p.stderr.strip()))
    return outs
build={n:{'path':p,'sha256':sha(open(p,'rb').read())[:16],
          'mtime':datetime.datetime.utcfromtimestamp(os.path.getmtime(p)).strftime('%Y-%m-%dT%H:%M:%SZ')} for n,p in ENG}
build['cpython']={'path':'/usr/local/bin/python3','version':subprocess.run(['/usr/local/bin/python3','-V'],capture_output=True,text=True).stdout.strip()}
print(json.dumps(build,indent=1))
def verdict(prog,runs=5):
    cp=run('/usr/local/bin/python3',prog,runs)
    v={'cpython':{'exit':cp[0][0],'stdout_sha256':sha(cp[0][1])[:16],'runs':runs,
                  'distinct_stdout':len({o[1] for o in cp}),'matches_expect':all(o[1]==T['expect_stdout'] and o[0]==0 for o in cp)},
       'engines':{}}
    route=None
    for n,p in ENG:
        o=run(p,prog,1)[0]
        if o[0]==90:
            v['engines'][n]={'exit':90,'stderr':o[2]}
        else:
            v['engines'][n]={'exit':o[0],'stdout_equals_cpython':o[1]==cp[0][1]}
            if route is None: route=n
    v['route']=route or 'cpython'
    v['tier1']=route is not None
    return v
out={}
for x in progs:
    out[sha(x['program'])[:12]]={'program':x['program'],'v':verdict(x['program'])}
gold=[k for k,v in out.items() if v['v']['tier1'] and v['v']['cpython']['matches_expect']]
neg=[k for k,v in out.items() if not v['v']['tier1'] and v['v']['cpython']['matches_expect']]
