import pathlib
p = pathlib.Path("src/route.rs"); s = p.read_text()

old = '''    Variant { name: "lypning-l", caps: &["cap-collections"] },'''
new = '''    Variant { name: "lypning-l", caps: &["cap-collections", "cap-hashlib"] },'''
assert s.count(old) == 1
s = s.replace(old, new)

old = '''/// `cap-collections` serves the `collections` MODULE and answers no runtime
/// kind: the `collections` kind it raises is a refusal a larger sibling would
/// raise identically (there is no larger sibling, and the surface it refuses —
/// error messages, multiset arithmetic, `.elements()` — is refused BECAUSE it
/// is CPython's to answer, not because these bytes are missing). An empty kind
/// list is the honest one; a kind listed here would cost a spawn to be told no
/// a second time.
pub const CAPS: &[(&str, &[&str], &[&str])] = &[("cap-collections", &["collections"], &[])];'''
new = '''/// `cap-collections` serves the `collections` MODULE and answers no runtime
/// kind: the `collections` kind it raises is a refusal a larger sibling would
/// raise identically (there is no larger sibling, and the surface it refuses —
/// error messages, multiset arithmetic, `.elements()` — is refused BECAUSE it
/// is CPython's to answer, not because these bytes are missing). An empty kind
/// list is the honest one; a kind listed here would cost a spawn to be told no
/// a second time.
///
/// `cap-hashlib` serves the `hashlib` MODULE, and its kind list is empty for
/// the same reason: every `hashlib` refusal is a message or a construct that is
/// CPython's to answer (`algorithms_guaranteed`, a `str` where bytes belong,
/// `usedforsecurity=`, an algorithm no variant computes), not a gap a larger
/// sibling would fill.
pub const CAPS: &[(&str, &[&str], &[&str])] = &[
    ("cap-collections", &["collections"], &[]),
    ("cap-hashlib", &["hashlib"], &[]),
];'''
assert s.count(old) == 1
s = s.replace(old, new)

old = '''    #[cfg(feature = "cap-collections")]
    if crate::collections::known_method(name) {
        return true;
    }'''
new = '''    #[cfg(feature = "cap-collections")]
    if crate::collections::known_method(name) {
        return true;
    }
    // The same reason: a hash object is its own `Value`, and there is no probe
    // for one here — `.hexdigest()` on the result of `hashlib.sha256(b"x")` is
    // exactly the program `cap-hashlib` exists to run.
    #[cfg(feature = "cap-hashlib")]
    if crate::hashlib::known_method(name) {
        return true;
    }'''
assert s.count(old) == 1
s = s.replace(old, new)
p.write_text(s)
