import subprocess, sys, os, tempfile, shutil, json

BINS = {
    "lypning": "/tmp/lyp-typename/bin/lypning",
    "lypning-l": "/tmp/lyp-typename/bin/lypning-l",
}
CPY = "/opt/homebrew/opt/python@3.14/bin/python3.14"

def run(cmd, prog, cwd):
    p = subprocess.run([cmd, "-c", prog], capture_output=True, cwd=cwd, timeout=25)
    return p.stdout, p.stderr, p.returncode

def main(path):
    progs = [l.rstrip("\n") for l in open(path) if l.strip() and not l.startswith("#@")]
    progs = [p.replace("\\n", "\n") for p in progs]
    base = tempfile.mkdtemp(prefix="lypdiff-")
    bad = []
    stats = {e: {"same":0, "refuse":0, "mismatch":0} for e in BINS}
    for i, prog in enumerate(progs):
        cd = os.path.join(base, "cpy%d" % i); os.makedirs(cd)
        try:
            co, ce, cr = run(CPY, prog, cd)
        except subprocess.TimeoutExpired:
            co, ce, cr = b"<TIMEOUT>", b"", -1
        for eng, binp in BINS.items():
            ed = os.path.join(base, "%s%d" % (eng, i)); os.makedirs(ed)
            try:
                eo, ee, er = run(binp, prog, ed)
            except subprocess.TimeoutExpired:
                eo, ee, er = b"<TIMEOUT>", b"", -1
            if er == 90:
                ok = (eo == b"") and ee.count(b"\n") == 1 and ee.startswith(eng.encode()+b": unsupported: ")
                if ok:
                    stats[eng]["refuse"] += 1; continue
                bad.append((eng, prog, (co,ce,cr), (eo,ee,er), "bad-refusal"))
                stats[eng]["mismatch"] += 1; continue
            if (eo, ee, er) == (co, ce, cr):
                stats[eng]["same"] += 1; continue
            kind = "wrong-answer-exit-0" if (er == 0 and cr == 0) else ("wrong-exit-code" if eo==co else "diff")
            bad.append((eng, prog, (co,ce,cr), (eo,ee,er), kind))
            stats[eng]["mismatch"] += 1
    print(json.dumps(stats, indent=1))
    print("TOTAL programs:", len(progs))
    for eng, prog, c, e, kind in bad:
        print("="*70)
        print("[%s] %s" % (kind, eng))
        print("PROG: %r" % prog)
        print("  cpy: rc=%d out=%r err=%r" % (c[2], c[0][:400], c[1][:400]))
        print("  eng: rc=%d out=%r err=%r" % (e[2], e[0][:400], e[1][:400]))
    shutil.rmtree(base, ignore_errors=True)

main(sys.argv[1])

