import json, os, sys, pathlib, collections
sys.path.insert(0, "/Users/user/dev/lypning-capture-model/src")
from lypning import harvest, capture

root = pathlib.Path(os.path.expanduser("~/.claude/projects"))
files = harvest._transcript_files([root])
where = collections.defaultdict(set)   # id -> set(files)
py_main = py_sub = 0
for f in files:
    sub = "/subagents/" in str(f)
    try:
        text = f.read_text(encoding="utf-8", errors="replace")
    except OSError:
        continue
    for line in text.split("\n"):
        if '"tool_use"' not in line:
            continue
        try:
            ev = json.loads(line)
        except ValueError:
            continue
        msg = ev.get("message") if isinstance(ev, dict) else None
        if not isinstance(msg, dict):
            continue
        content = msg.get("content")
        if not isinstance(content, list):
            continue
        for b in content:
            if not isinstance(b, dict) or b.get("type") != "tool_use":
                continue
            bid = b.get("id")
            if isinstance(bid, str) and bid:
                where[bid].add(str(f))
            if b.get("name") != "Bash":
                continue
            inp = b.get("input")
            cmd = inp.get("command") if isinstance(inp, dict) else None
            if isinstance(cmd, str) and capture.looks_pythonish(cmd):
                if sub:
                    py_sub += 1
                else:
                    py_main += 1
dupes = {k: v for k, v in where.items() if len(v) > 1}
print("transcript files scanned      %d" % len(files))
print("distinct tool_use ids         %d" % len(where))
print("ids appearing in >1 file      %d" % len(dupes))
tot = py_main + py_sub
print("pythonish Bash tool_use blocks %d  (main %d, subagent %d)" % (tot, py_main, py_sub))
if tot:
    print("subagent share                 %.1f%%" % (100.0 * py_sub / tot))

