    if hyphen_non_ascii {
        return Some(format!(
            "textwrap.{name}() over a non-ASCII text holding a '-': the hyphen rule reads \\
             Python's \\\\w and [^\\\\d\\\\W], which are the Unicode character database's to answer"
        ));
    }
    (ty != "str").then(|| format!("textwrap.{name}() over a {ty} (CPython requires a str)"))
}

/// The `width` argument's three refusals, all properties of the width alone —
/// which is why they are decided before the wrapper runs rather than inside it.
///
/// A `bool` IS an `int` in CPython and `width=True` really is 1. The other two
/// are CPython's own `ValueError`s, whose wording is CPython's to print:
/// `invalid width %r (must be > 0)`, and — for `shorten` alone, which is the
/// only caller that sets `max_lines` — `placeholder too large for max width`,
/// which with no indent is `len(' [...]'.lstrip()) > width`, i.e. `width < 5`.
///
/// `n` is `None` for a width whose VALUE the caller could not read, which is
/// every non-int at runtime and every non-literal in the walk; a `None` with an
/// int type is therefore served, and the runtime call asks again.
#[cfg(feature = "cap-textwrap")]
pub fn textwrap_width_block(name: &str, ty: &str, n: Option<i64>) -> Option<String> {
    if ty != "int" && ty != "bool" {
        return Some(format!(
            "textwrap.{name}(width=…) that is a {ty} (CPython requires an int)"
        ));
    }
    match n {
        Some(n) if n < 1 => Some(format!(
            "textwrap.{name}(width={n}), which CPython rejects with a ValueError this engine \\
             does not word"
        )),
        Some(n) if n < 5 && name == "shorten" => Some(format!(
            "textwrap.shorten(width={n}), which is too narrow for the ' [...]' placeholder and \\
             which CPython rejects with a ValueError this engine does not word"
        )),
        _ => None,
    }
}

/// Every refusal a served `textwrap` call can raise that a walk can decide,
/// hoisted out of the run and into the walk (#51): the argument COUNT and the
/// keyword NAMES, which the source always spells, and the `text` and `width`
/// when the source spells those too.
///
/// Only `textwrap.<name>(...)` through the module or an alias of it. A name
/// bound by `from textwrap import fill` is NOT tracked, and deliberately: it
/// would need a binding vector on [`Requirements`] that every program pays for
/// in bytes, the corpus (mined 2026-09-07, 3,688 entries) spells the module
/// form in all six of its textwrap programs, and the runtime backstop in
/// `textwrap::call` refuses the other spelling at exit 90 with the commit
/// barrier still holding the output.
#[cfg(feature = "cap-textwrap")]
fn textwrap_call_block(
    req: &mut Requirements,
    func: &Expr,
    args: &[Expr],
    kwargs: &[(std::rc::Rc<str>, Expr)],
    star: &[usize],
    dstar: &[Expr],
) {
    let Expr::Attr(b, n) = func else { return };
    if !req.imports.contains("textwrap")
        || !matches!(resolve_module(b, &req.aliases), Some(crate::value::Value::Module("textwrap")))
    {
        return;
    }
    let Some(name) = TEXTWRAP_SERVED.iter().copied().find(|x| *x == n.as_ref()) else { return };
    let Some((pos, kws)) = flatten_call(args, kwargs, star, dstar) else { return };
    let max_pos = if name == "dedent" { 1 } else { 2 };
    let detail = kws
        .iter()
        .find_map(|(k, _)| textwrap_kw_block(name, k))
        .or_else(|| {
            (pos.is_empty() || pos.len() > max_pos || (pos.len() == max_pos && !kws.is_empty()))
                .then(|| {
                    format!("textwrap.{name}() with {} positional argument(s)", pos.len())
                })
        })
        .or_else(|| {
            let e = pos.first()?;
            let hyphen_non_ascii =
                matches!(e, Expr::Str(t) if !t.is_ascii() && t.contains('-'));
            textwrap_text_block(name, literal_type(e)?, hyphen_non_ascii)
        })
        .or_else(|| {
            let e = pos.get(1).copied().or_else(|| kws.first().map(|(_, v)| *v))?;
            let n = match e {
                Expr::Int(i) => i.small(),
                Expr::True => Some(1),
                Expr::False => Some(0),
                _ => None,
            };
            textwrap_width_block(name, literal_type(e)?, n)
        });
    if let Some(d) = detail {
        // `stop_only`, not `stop`: the `--plan` row for these programs is
        // `module: import textwrap`, which is what the CORE — the binary that
        // routes, and the one with none of this compiled in — sees, and what
        // the build order should keep ranking.
        req.stop_only("textwrap", d);
    }
}

