import subprocess, sys
L="/root/.lypning/bin/lypning"; C="/usr/bin/python3"

CONVS = ['d','i','u','s','r','f','F','e','E','g','G','x','X','o','c']
FLAGS = ['', '-', '+', ' ', '#', '0', '-0', '+0', '# ', '-+']
WIDTHS = ['', '1', '5', '10']
PRECS  = ['', '.', '.0', '.2', '.7']
NUMS   = ['0','1','-1','42','-42','255','1.5','-1.5','0.0','1e10','1e-10','True','False']
STRS   = ["''","'a'","'hello'","'\\u00e9'"]

def cell_prog(spec, val):
    return ("try:\n    print(repr(%r %% (%s,)))\nexcept TypeError:\n    print('TypeError')\n"
            "except ValueError as e:\n    print('ValueError')\n" % (spec, val))

def chunk_prog(cells):
    lines = ["out = []"]
    for spec, val in cells:
        lines.append("try:\n    out.append(repr(%r %% (%s,)))\nexcept TypeError:\n    out.append('TypeError')\n"
                     "except ValueError:\n    out.append('ValueError')" % (spec, val))
    lines.append("print('~'.join(out))")
    return "\n".join(lines)

def run(binp, prog):
    p = subprocess.run([binp,"-c",prog],capture_output=True,text=True,timeout=60)
    return p.returncode, p.stdout.strip(), p.stderr.strip()

cells = []
for c in CONVS:
    pool = STRS if c in ('s','r') else NUMS
    for fl in FLAGS:
        for w in WIDTHS:
            for pr in PRECS:
                for v in pool:
                    cells.append(('%'+fl+w+pr+c, v))
print("grid: %d cells" % len(cells))

# Chunk so a single refusal costs one chunk, then re-run that chunk cell by cell.
CH = 200
bad = 0; refused = 0; checked = 0
for k in range(0, len(cells), CH):
    ch = cells[k:k+CH]
    prog = chunk_prog(ch)
    ra, oa, ea = run(L, prog)
    rb, ob, eb = run(C, prog)
    if ra == 90:
        for spec, val in ch:
            cp = cell_prog(spec, val)
            r1,o1,_ = run(L, cp); r2,o2,_ = run(C, cp)
            if r1 == 90: refused += 1; continue
            checked += 1
            if (r1,o1) != (r2,o2):
                bad += 1
                if bad <= 12: print("  DIFF %-14s %% %-8s lyp=%-24s cpy=%s" % (spec, val, o1[:24], o2[:30]))
        continue
    assert ra == 0 and rb == 0, (ra, rb, ea[-200:], eb[-200:])
    xs, ys = oa.split('~'), ob.split('~')
    for (spec, val), x, y in zip(ch, xs, ys):
        checked += 1
        if x != y:
            bad += 1
            if bad <= 12: print("  DIFF %-14s %% %-8s lyp=%-24s cpy=%s" % (spec, val, x[:24], y[:30]))
print("checked %d, refused %d (fine), %d DIFFERING" % (checked, refused, bad))
sys.exit(1 if bad else 0)

