from pipeline.stats import SEED
def blocks(scores,B=10000,seed=SEED):
    rng=random.Random(seed); n=len(scores); vals=list(scores)
    m=sorted(sum(rng.choices(vals,k=n))/n for _ in range(B))
    def run_at(i):
        lo=i
        while lo>0 and m[lo-1]==m[i]: lo-=1
        hi=i
        while hi<B-1 and m[hi+1]==m[i]: hi+=1
        return lo,hi
    return m, run_at(250), run_at(9750)
