block = '''/// Decide a `math` call in the WALK, wherever the source says enough to decide
/// it — so a refusal lands before the program starts rather than after it.
///
/// **This is the whole reason the rule lives in one function.** `crate::math::check`
/// is the same procedure the evaluator runs, asked here with
/// [`crate::math::Arg::Unknown`] standing in for every argument a walk cannot
/// read. It therefore cannot drift from the runtime's answer, and every literal
/// call it can settle — `math.sqrt(2)`, `math.factorial(30)`, `math.gcd('a', 2)`,
/// a keyword, a wrong count — becomes a static block. That matters because
/// `os.mkdir` calls `io::mark_committed` the moment it runs: from there on ANY
/// refusal is exit 1 with the side effect on disk and no answer, where a static
/// one is a clean 90 the chain acts on (issue #51, `docs/HILLCLIMB.md` 77).
///
/// What is left at runtime is exactly what no walk could hoist: an argument
/// whose VALUE is computed. `math.isqrt(n)` for a bound `n`, `math.ceil(x/y)`,
/// `math.factorial(len(s))` — the value decides, and only the evaluator has it.
/// The same is true of a call reached through `from math import isqrt`, whose
/// callee is a bare name this walk does not resolve to the module.
///
/// Behind `cfg(feature = "cap-math")` on purpose: the block predicts a refusal
/// the CORE would never raise (the core stops at `module: import math` and
/// routes onward), so carrying it there would be bytes in a frozen binary for
/// an answer it cannot use. The known cost is issue #48 — the routing census
/// cannot see these blocks, because the chain enters at the core.
#[cfg(feature = "cap-math")]
fn math_call_block(
    req: &mut Requirements,
    func: &Expr,
    args: &[Expr],
    kwargs: &[(std::rc::Rc<str>, Expr)],
    star: &Option<Box<Expr>>,
    dstar: &Option<Box<Expr>>,
) {
    // `math.<name>(…)`, and only that spelling: a bare name from
    // `from math import …` is not resolved here and keeps the runtime backstop.
    let Expr::Attr(base, name) = func else { return };
    if !matches!(resolve_module(base, &req.aliases), Some(crate::value::Value::Module("math"))) {
        return;
    }
    if !crate::math::is_func(name) {
        // `math.fmod(…)` — the `Expr::Attr` arm blocks it as `module-attr`
        // whether or not it is called, and this must not displace that row.
        return;
    }
    // Every `math` function is a positional-only C function, so a keyword is a
    // TypeError whatever its name — and a splat hides the argument COUNT, which
    // is the one thing decided before any value is.
    if !kwargs.is_empty() || star.is_some() || dstar.is_some() {
        req.block(
            "math-domain",
            format!("math.{name}() with keyword or unpacked arguments"),
        );
        return;
    }
    let as_args: Vec<crate::math::Arg> = args.iter().map(math_arg).collect();
    if let Err(e) = crate::math::check(name, &as_args) {
        if let crate::err::ErrKind::Unsupported { kind, detail } = e.kind() {
            req.block(kind, detail.clone());
        }
    }
}

/// One argument as the WALK can see it. A literal number is its value; a
/// literal of another type is the TypeError CPython raises; everything else is
/// a value only the runtime will know.
#[cfg(feature = "cap-math")]
fn math_arg(e: &Expr) -> crate::math::Arg {
    use crate::math::Arg;
    match e {
        Expr::Int(i) => Arg::Int(*i),
        Expr::Float(f) => Arg::Float(*f),
        Expr::True => Arg::Int(1),
        Expr::False => Arg::Int(0),
        // `math.factorial(-1)` is written as a negation of a literal, and it is
        // the shape the domain rule most needs to see.
        Expr::Un(UnOp::Neg, inner) => match math_arg(inner) {
            Arg::Int(i) => i.checked_neg().map(Arg::Int).unwrap_or(Arg::Unknown),
            Arg::Float(f) => Arg::Float(-f),
            _ => Arg::Unknown,
        },
        Expr::Un(UnOp::Pos, inner) => math_arg(inner),
        Expr::Str(_) | Expr::Bytes(_) | Expr::None | Expr::List(_) | Expr::Dict(_)
        | Expr::Tuple(_) | Expr::Set(_) => Arg::NotNum,
        _ => Arg::Unknown,
    }
}

