SEX = set(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/")
def model(data, urlsafe=False):
    if urlsafe:
        data = data.translate(bytes.maketrans(b'-_', b'+/'))
    n = 0; pads = 0
    for c in data:
        if c in SEX: n += 1; pads = 0
        elif c == 0x3d: pads += 1
    rem = n % 4
    if rem == 1: return "RAISE"
    if rem != 0 and pads < 4 - rem: return "RAISE"
    acc = 0; bits = 0; out = bytearray()
    for c in data:
        if c not in SEX: continue
        v = bytes(base64.standard_b64encode(b'')) # placeholder
    # decode
    ALPHA = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    idx = {c:i for i,c in enumerate(ALPHA)}
    acc=0;bits=0;out=bytearray()
    for c in data:
        if c not in idx: continue
        acc = (acc<<6)|idx[c]; bits += 6
        if bits>=8:
            bits-=8; out.append((acc>>bits)&0xFF)
    return bytes(out)

def cpy(data, urlsafe=False):
    try:
        return base64.urlsafe_b64decode(data) if urlsafe else base64.b64decode(data)
    except Exception:
        return "RAISE"

