fn reject_unknown_kw(func: &str, kw: &[(Rc<str>, Value)], allowed: &[&str]) -> R<()> {
    for (k, _) in kw {
        if !allowed.contains(&k.as_ref()) {
            return Err(unknown_kw(func, k));
        }
    }
    Ok(())
