/// a refusal is one reason and belongs in one place — and because a site that
/// went back to writing the text would then be a visible edit rather than a
/// line that looks like all the others.
pub(crate) fn unknown_kw(func: &str, k: &str) -> LypningError {
    version_dependent(
        &format!("{func}() handed a keyword it does not take ('{k}')"),
        "3.13",
    )
}
