'''            if let Some(crate::value::Value::Module(m)) = resolve_module(b, &req.aliases) {
                if crate::modules::get_attr(&crate::value::Value::Module(m), n).is_err() {
                    req.block("module-attr", format!("{m}.{n}"));
                    // …and, for a module whose served surface is a TABLE, the
                    // STOP as well. [`MODULE_ATTRS`] exists because a `module`
                    // claim admits every program that imports the module into
                    // the variant, including the ones reaching for a name it
                    // does not serve — and on the `-c` path the variant is
                    // entered by, that decline is a RUNTIME refusal, which
                    // after a committed side effect is exit 1 with the output
                    // discarded (issue #51). Recorded here, [`static_check`]
                    // raises it before `Interp::new()` instead.
                    if MODULE_ATTRS.iter().any(|(mm, _)| *mm == m) {
                        req.stop_only("module-attr", format!("{m}.{n}"));
                    }
                }
                return;
            }''')

