def prog(chunk):
    out = []
    for j, c in enumerate(chunk):
        out += ["try:", "    %s" % c, "    print(%d, 'ok')" % j,
                "except NameError as e:", "    print(%d, 'err', e)" % j]
    return "\n".join(out) + "\n"
def run(b, s):
