from __future__ import annotations
import itertools, subprocess, sys, tempfile, os

Q = ["", "*", "*?", "+", "+?", "?", "??", "{1,2}", "{1,2}?", "{2,3}", "{2,3}?",
     "{2}", "{2}?", "{0,2}", "{1,}", "{1,}?", "{2,}", "{3,4}?"]
BODIES = ["a", "a|b", "ab", "a|", "(?:a|bb)", "[ab]", "\\w", "a?b"]
SUBJ = ["", "a", "b", "ab", "ba", "aa", "bb", "aab", "abb", "aba", "abab", "aaab", "abc", "x"]

def gen():
    out = []
    # 2-deep: ( body Q1 ) Q2   and non-capturing, plus a tail
    for b, q1, q2, g, t in itertools.product(BODIES, Q, Q, ["(%s)", "(?:%s)"], ["", "b", "$", "c"]):
        out.append(g % ("(?:%s)%s" % (b, q1)) + q2 + t)
    # 3-deep with a group at each level
    for q1, q2, q3 in itertools.product(Q, repeat=3):
        out.append("((a%s)%s)%s" % (q1, q2, q3))
        out.append("((?:(a%s)%s)%s)b" % (q1, q2, q3))
    # two groups side by side inside a counted repeat
    for q1, q2, q3 in itertools.product(Q, repeat=3):
        out.append("(?:(a%s)(b%s))%s" % (q1, q2, q3))
    seen, uniq = set(), []
    for p in out:
        if p not in seen:
            seen.add(p); uniq.append(p)
    return uniq

