    r = [None if m is None else (m.span(), m.groups(), [m.span(i) for i in range(1, (m.re.groups or 0) + 1)])]
    for f in (lambda: re.findall(p, s), lambda: re.split(p, s),
              lambda: re.sub(p, "<\\1>" if re.compile(p).groups else "<>", s),
              lambda: [(x.span(), x.groups()) for x in re.finditer(p, s)],
              lambda: (lambda mm: None if mm is None else (mm.span(), mm.groups()))(re.match(p, s)),
              lambda: (lambda mm: None if mm is None else (mm.span(), mm.groups()))(re.fullmatch(p, s))):
