"""Differential runner: program on lypning-l vs CPython, each in a fresh temp cwd."""
import os, subprocess, sys, tempfile, shutil

LL = os.environ.get("LL", "/tmp/lyp-cap-csv2/bin/lypning-l")
CP = os.environ.get("CP", "/opt/homebrew/Cellar/python@3.14/3.14.5/Frameworks/Python.framework/Versions/3.14/bin/python3.14")

def run(exe, prog, stdin=b"", extra=None):
    d = tempfile.mkdtemp(prefix="dgrid-")
    try:
        cmd = [exe, "-c", prog] + (extra or [])
        p = subprocess.run(cmd, cwd=d, input=stdin, capture_output=True, timeout=30)
        err = p.stderr.decode("utf-8", "replace").rstrip("\n").split("\n")[-1] if p.stderr.strip() else ""
        return p.returncode, p.stdout.decode("utf-8", "replace"), err
    finally:
        shutil.rmtree(d, ignore_errors=True)

def cmp1(prog, stdin=b"", label="", extra=None, quiet=False):
    lrc, lout, lerr = run(LL, prog, stdin, extra)
    crc, cout, cerr = run(CP, prog, stdin, extra)
    if lrc == 90:
        ok = (lout == "")
        verdict = "REFUSE-OK" if ok else "REFUSE-WITH-STDOUT"
    elif (lrc, lout, lerr) == (crc, cout, cerr):
        ok, verdict = True, "match"
    else:
        ok, verdict = False, "DIFF"
    if not quiet or not ok or verdict == "REFUSE-WITH-STDOUT":
        print(f"[{verdict}] {label or prog[:60]!r}")
        if verdict in ("DIFF", "REFUSE-WITH-STDOUT"):
            print(f"    lyp: rc={lrc} out={lout!r} err={lerr!r}")
            print(f"    cpy: rc={crc} out={cout!r} err={cerr!r}")
        elif verdict == "REFUSE-OK":
            print(f"    90:  {lerr!r}   (cpython rc={crc} out={cout!r})")
    return ok and verdict != "REFUSE-WITH-STDOUT", verdict

import sys
