///
/// `newline='\\n'` — and every BINARY stream, which takes no `newline=` at all —
/// ends a line at `\\n` and nowhere else. The other two recognise all three
/// endings: `\\r\\n`, `\\n` and a bare `\\r`. They differ only in what the line
/// then LOOKS like, which is [`line_text`]'s half.
#[cfg(feature = "cap-csv")]
fn line_end(fo: &mio::FileObj, start: usize) -> usize {
    if fo.binary || fo.newline_mode == mio::NEWLINE_KEEP_NL {
        return match fo.data[start..].iter().position(|c| *c == b'\\n') {
            Some(i) => start + i + 1,
            None => fo.data.len(),
        };
    }
    match fo.data[start..].iter().position(|c| *c == b'\\n' || *c == b'\\r') {
        Some(i) => {
            let e = start + i;
            if fo.data[e] == b'\\r' && fo.data.get(e + 1) == Some(&b'\\n') {
                e + 2
            } else {
                e + 1
            }
        }
        None => fo.data.len(),
    }
}

/// The line itself. `newline=None` — the default, and the only mode that
/// TRANSLATES — hands `\\r\\n` and a bare `\\r` to the program as `\\n`.
///
/// The whole translation is the terminator, which is why this is three lines
/// and not a scan: [`line_end`] stopped at the first `\\r` or `\\n`, so the only
/// carriage return a line can contain is the one it ends with.
#[cfg(feature = "cap-csv")]
fn line_text(fo: &mio::FileObj, start: usize, end: usize) -> R<std::rc::Rc<str>> {
    let raw = &fo.data[start..end];
    if fo.newline_mode == mio::NEWLINE_UNIVERSAL && raw.last() == Some(&b'\\r') {
        let mut s = decode_text(&raw[..raw.len() - 1], LINE_UTF8)?.to_string();
        s.push('\\n');
        return Ok(std::rc::Rc::from(s.as_str()));
    }
    if fo.newline_mode == mio::NEWLINE_UNIVERSAL && raw.ends_with(b"\\r\\n") {
        let mut s = decode_text(&raw[..raw.len() - 2], LINE_UTF8)?.to_string();
        s.push('\\n');
        return Ok(std::rc::Rc::from(s.as_str()));
    }
    decode_text(raw, LINE_UTF8)
}

