def rebuild(got, *, out=None, err=None, rc=None):
    kw = {}
    if out is not None: kw.update(stdout_raw=out, stdout=eng._as_text(out))
    if err is not None:
        eb = err.encode() if isinstance(err, str) else err
        kw.update(stderr_raw=eb, stderr=eng._as_text(eb))
    if rc is not None: kw["returncode"] = rc
