def survivors(fn, arm):
    out = []
    for engine, entry, ref, got, v in by[arm]:
        if v.verdict != C.MATCH: continue
        g2 = fn(entry, ref, got, engine)
        if g2.stdout_bytes == got.stdout_bytes and (g2.stderr or "") == (got.stderr or "") \
           and g2.returncode == got.returncode:
            continue
        if C.classify(ref, g2, engine, entry).verdict == C.MATCH:
            out.append((entry, ref, got))
