def run(exe, prog, cwd):
    os.makedirs(cwd, exist_ok=True)
    try:
        p = subprocess.run([exe, "-c", prog], cwd=cwd, capture_output=True, timeout=20)
        return p.returncode, p.stdout, p.stderr
