/// CPython's wording, which distinguishes an exact count from a range.
fn check_arity(ty: &str, name: &str, args: &Args) -> R<()> {
    let Some((lo, hi)) = arity(ty, name) else { return Ok(()) };
    let n = args.len();
    if n >= lo && n <= hi {
        return Ok(());
    }
    Err(type_err(if lo == hi {
        format!("{ty}.{name}() takes exactly {lo} argument(s) ({n} given)")
    } else if n > hi {
        format!("{ty}.{name}() takes at most {hi} argument(s) ({n} given)")
    } else {
        format!("{ty}.{name}() takes at least {lo} argument(s) ({n} given)")
    }))
}

