"""Is a case satisfiable at all? The negative program is correct Python by the
corpus's own definition, so if running it does not reproduce expect_stdout the
expected output is not reproducible and nothing can pass the case."""
import json, sys, collections
sys.path.insert(0, "/home/user/lypning/nemotron")
from pipeline import sandbox

rows=[]
for line in open(sys.argv[1]):
    c=json.loads(line)
    t=c.get("test") or {}
    if t.get("kind") != "lypning" or "expect_stdout" not in t: 
        rows.append((c["id"], "not-a-stdout-case", "")); continue
    negs=c.get("negatives") or []
    if not negs:
        rows.append((c["id"], "no-negative", "")); continue
    r1=sandbox.run_python(negs[0]["program"], timeout_s=10)
    r2=sandbox.run_python(negs[0]["program"], timeout_s=10)
    want=t["expect_stdout"]
    if r1.stdout != r2.stdout:
        rows.append((c["id"], "UNSTABLE", repr(r1.stdout[:40])+" vs "+repr(r2.stdout[:40])))
    elif r1.stdout != want:
        rows.append((c["id"], "UNREPRODUCIBLE", "want "+repr(want[:46])+" got "+repr(r1.stdout[:46])))
    else:
        rows.append((c["id"], "ok", ""))
t=collections.Counter(v for _,v,_ in rows)
print("n=%d  " % len(rows) + "  ".join("%s=%d"%kv for kv in sorted(t.items())))
for i,v,d in rows:
    if v in ("UNSTABLE","UNREPRODUCIBLE"): print("  %-16s %s  %s" % (v, i, d))

def fix(p, pairs):
    s=open(p).read()
    for o,n in pairs:
        assert o in s, p+" MISSING: "+repr(o[:110])
        s=s.replace(o,n,1)
    open(p,"w").write(s)

