def cls(s):
    m=re.match(r"^(.?)([<>=^]?)([-+ ]?)(#?)(0?)(\d*)([,_]?)(?:\.(\d+))?([a-zA-Z%]?)$",s)
    if not m: return "UNPARSED:"+s
    fill,align,sign,hsh,zero,width,grp,prec,typ=m.groups()
    tags=[]
    if fill: tags.append("fill")
    if align: tags.append("align"+align)
    if hsh: tags.append("#")
    if zero: tags.append("zero")
    if width and width!="0": tags.append("W")
    if grp: tags.append("grp")
    if prec is not None: tags.append("prec")
    tags.append("t="+(typ or "NONE"))
    return "|".join(tags)
