"""Differential quantifier cross-product: lypning-l vs CPython, in ONE spawn each."""
from __future__ import annotations
import itertools, json, subprocess, sys, tempfile, os

QUANT = ["", "*", "*?", "+", "+?", "?", "??",
         "{2}", "{2}?", "{0,2}", "{0,2}?", "{1,2}", "{1,2}?", "{1,3}", "{1,3}?",
         "{2,3}", "{2,3}?", "{2,4}", "{2,4}?", "{0,3}", "{3}", "{1,}", "{1,}?",
         "{2,}", "{2,}?", "{0,}", "{0,}?"]
ATOMS = ["a", "a|b", "ab", "."]
SUBJ = ["", "a", "b", "aa", "ab", "aab", "aaa", "a.b", "ba", "abab", "xaby", "aaab"]
TAILS = ["", "b", "$"]

def patterns():
    out = []
    for inner, outer in itertools.product(QUANT, repeat=2):
        for atom in ATOMS:
            for grp in ("(%s)", "(?:%s)"):
                body = "a" + inner if atom == "a" else "(?:%s)%s" % (atom, inner)
                for tail in TAILS:
                    out.append(grp % body + outer + tail)
    # de-dup, keep order
    seen, uniq = set(), []
    for p in out:
        if p not in seen:
            seen.add(p); uniq.append(p)
    return uniq

PROBE = r'''
import re, sys
def one(p, s):
    try:
        m = re.search(p, s)
    except Exception as e:
        return "E:" + type(e).__name__
    r = [None if m is None else (m.span(), m.group(0), m.groups())]
    try: r.append(re.findall(p, s))
    except Exception as e: r.append("E:" + type(e).__name__)
    try: r.append(re.split(p, s))
    except Exception as e: r.append("E:" + type(e).__name__)
    try: r.append(re.sub(p, "<\\g<0>>", s))
    except Exception as e: r.append("E:" + type(e).__name__)
    try: r.append([(mm.span(), mm.groups()) for mm in re.finditer(p, s)])
    except Exception as e: r.append("E:" + type(e).__name__)
    try:
        mm = re.match(p, s); r.append(None if mm is None else (mm.span(), mm.groups()))
    except Exception as e: r.append("E:" + type(e).__name__)
    try:
        mm = re.fullmatch(p, s); r.append(None if mm is None else (mm.span(), mm.groups()))
    except Exception as e: r.append("E:" + type(e).__name__)
    return r
PAT = __PATS__
SUB = __SUBJ__
for p in PAT:
    for s in SUB:
        print(repr(p), repr(s), one(p, s), flush=True)
'''

def run(exe, pats, subj):
    prog = PROBE.replace("__PATS__", repr(pats)).replace("__SUBJ__", repr(subj))
    with tempfile.TemporaryDirectory() as d:
        return subprocess.run([exe, "-c", prog], capture_output=True, text=True, cwd=d, timeout=1800)

def main():
    exe = sys.argv[1]
    pats = patterns()
    if len(sys.argv) > 2 and sys.argv[2] == "--count":
        print(len(pats)); return
    CHUNK = 200
    bad = 0; total = 0; refused = 0
    for i in range(0, len(pats), CHUNK):
        chunk = pats[i:i+CHUNK]
        g = run(exe, chunk, SUBJ)
        r = run(sys.executable, chunk, SUBJ)
        if g.returncode == 90:
            # whole chunk refused; fall back one pattern at a time
            for p in chunk:
                g1 = run(exe, [p], SUBJ); r1 = run(sys.executable, [p], SUBJ)
                if g1.returncode == 90:
                    refused += 1; continue
                total += 1
                if (g1.stdout, g1.returncode) != (r1.stdout, r1.returncode):
                    bad += 1
                    if bad <= 25:
                        for a, b in zip(g1.stdout.splitlines(), r1.stdout.splitlines()):
                            if a != b:
                                print("MISMATCH", a, "\n     cpy:", b); break
            continue
        total += len(chunk)
        if (g.stdout, g.returncode) != (r.stdout, r.returncode):
            gl, rl = g.stdout.splitlines(), r.stdout.splitlines()
            shown = 0
            for a, b in zip(gl, rl):
                if a != b:
                    bad += 1
                    if shown < 6 and bad <= 60:
                        print("MISMATCH lyp:", a, "\n          cpy:", b)
                        shown += 1
            if len(gl) != len(rl):
                print("LENGTH", len(gl), len(rl), "exit", g.returncode, r.returncode, g.stderr[-200:])
                bad += 1
    print("patterns %d  refused %d  measured %d  mismatching-rows %d" % (len(pats), refused, total, bad))

main()

