    let n = n as i64;
    let clamp = |v: i64| -> i64 {
        let v = if v < 0 { n + v } else { v };
        v.clamp(0, n)
    };
    let start = lo.map_or(0, clamp);
    let stop = hi.map_or(n, clamp).max(start);
    (start as usize, stop as usize)
}

