WRAPS={"len","set","frozenset","sum","min","max","any","all","sorted"}
def analyse(src, taint_names=False):
    t=ast.parse(src); parent={}
    for n in ast.walk(t):
        for c in ast.iter_child_nodes(n): parent[c]=n
    tainted=set()
    if taint_names:
        for n in ast.walk(t):
            if isinstance(n, ast.Assign) and isinstance(n.value, ast.Call):
                f=n.value.func
                if isinstance(f,ast.Attribute) and isinstance(f.value,ast.Name) and f.value.id=="glob" and f.attr in("glob","iglob"):
                    for tg in n.targets:
                        if isinstance(tg,ast.Name): tainted.add(tg.id)
    bad=[]
    def ok_wrap(p, n):
        if isinstance(p, ast.Call) and isinstance(p.func, ast.Name) and p.func.id in WRAPS and p.args and p.args[0] is n:
            if p.func.id in("sorted","min","max") and any(k.arg=="key" for k in p.keywords): return False
            if len(p.args)!=1: return False
            return True
        if isinstance(p, ast.Compare) and any(isinstance(o,(ast.In,ast.NotIn)) for o in p.ops) and n in p.comparators: return True
        return False
    for n in ast.walk(t):
        if isinstance(n, ast.Call):
            f=n.func
            if isinstance(f,ast.Attribute) and isinstance(f.value,ast.Name) and f.value.id=="glob" and f.attr in("glob","iglob"):
                if any(k.arg!="recursive" for k in n.keywords) or len(n.args)!=1: bad.append("kwargs/args"); continue
                if not ok_wrap(parent.get(n), n): bad.append(ast.dump(parent.get(n))[:40]); continue
        if taint_names and isinstance(n, ast.Name) and n.id in tainted and isinstance(n.ctx, ast.Load):
            p=parent.get(n)
            if isinstance(p, ast.Assign) and p.value is n: continue
