    Group(usize, Box<Node>),
    NonCap(Box<Node>),
    Alt(Vec<Node>),
    Seq(Vec<Node>),
    Rep { inner: Box<Node>, min: u32, max: u32, greedy: bool },
    Start,
    End,
    WordB,
    NotWordB,
    Backref(usize),
