fn is_word(c: char) -> bool { c.is_alphanumeric() || c == '_' }

struct M<'a> {
    text: &'a [char],
    flags: Flags,
    caps: Vec<Option<(usize, usize)>>,
    steps: u32,
}

impl<'a> M<'a> {
    fn eq(&self, a: char, b: char) -> bool {
        if self.flags.i { a.eq_ignore_ascii_case(&b) || a.to_lowercase().eq(b.to_lowercase()) } else { a == b }
    }
    fn class_hit(&self, ranges: &[(char, char)], neg: bool, c: char) -> bool {
        let mut hit = ranges.iter().any(|(lo, hi)| c >= *lo && c <= *hi);
        if !hit && self.flags.i {
            let lc = c.to_ascii_lowercase();
            let uc = c.to_ascii_uppercase();
            hit = ranges.iter().any(|(lo, hi)| (lc >= *lo && lc <= *hi) || (uc >= *lo && uc <= *hi));
