                ok && k(self, at)
            }
            Node::End => {
                let ok = at == self.text.len() || (self.flags.m && self.text.get(at) == Some(&'\n'))
                    || (at + 1 == self.text.len() && self.text.get(at) == Some(&'\n'));
                ok && k(self, at)
            }
            Node::WordB | Node::NotWordB => {
                let before = at > 0 && is_word(self.text[at - 1]);
                let after = at < self.text.len() && is_word(self.text[at]);
                let b = before != after;
                let want = matches!(node, Node::WordB);
                (b == want) && k(self, at)
            }
            Node::Backref(n) => {
                let Some(Some((s0, e0))) = self.caps.get(*n).copied() else { return false };
                let len = e0 - s0;
                if at + len > self.text.len() { return false; }
                for i in 0..len {
                    if !self.eq(self.text[s0 + i], self.text[at + i]) { return false; }
                }
                k(self, at + len)
            }
            Node::NonCap(inner) => self.m(inner, at, k),
            Node::Group(idx, inner) => {
                let idx = *idx;
                let saved = self.caps.get(idx).copied().flatten();
                let start = at;
                let ok = self.m(inner, at, &mut |me: &mut M<'a>, end: usize| {
                    let prev = me.caps[idx];
                    me.caps[idx] = Some((start, end));
                    if k(me, end) { true } else { me.caps[idx] = prev; false }
                });
                if !ok { if idx < self.caps.len() { self.caps[idx] = saved; } }
                ok
            }
            Node::Alt(branches) => {
                for b in branches {
                    if self.m(b, at, k) { return true; }
                }
                false
            }
            Node::Seq(items) => self.seq_from(items, 0, at, k),
            Node::Rep { inner, min, max, greedy } => self.rep(inner, *min, *max, *greedy, 0, at, k),
        }
    }
    fn seq_from(&mut self, items: &[Node], i: usize, at: usize, k: &mut dyn FnMut(&mut M<'a>, usize) -> bool) -> bool {
        if i == items.len() { return k(self, at); }
        let (head, rest) = (&items[i], items);
        // The continuation carries the tail of the sequence.
        let mut cont = |me: &mut M<'a>, p: usize| me.seq_from(rest, i + 1, p, k);
        self.m(head, at, &mut cont)
    }
    #[allow(clippy::too_many_arguments)]
    fn rep(&mut self, inner: &Node, min: u32, max: u32, greedy: bool, done: u32, at: usize,
           k: &mut dyn FnMut(&mut M<'a>, usize) -> bool) -> bool {
        if done < min {
            return self.m(inner, at, &mut |me: &mut M<'a>, p: usize| me.rep(inner, min, max, greedy, done + 1, p, k));
        }
        if greedy {
            if done < max {
                let more = self.m(inner, at, &mut |me: &mut M<'a>, p: usize| {
                    if p == at { return false; }
                    me.rep(inner, min, max, greedy, done + 1, p, k)
                });
                if more { return true; }
            }
            k(self, at)
        } else {
            if k(self, at) { return true; }
            if done < max {
                return self.m(inner, at, &mut |me: &mut M<'a>, p: usize| {
                    if p == at { return false; }
                    me.rep(inner, min, max, greedy, done + 1, p, k)
                });
            }
            false
        }
    }
}

struct Regex { node: Node, ngroups: usize, flags: Flags }

fn compile(pat: &str, flags: Flags) -> R<Regex> {
    let cleaned: String = if flags.x {
        let mut out = String::new();
        let mut esc = false;
        for c in pat.chars() {
            if esc { out.push(c); esc = false; continue; }
            if c == '\\' { out.push(c); esc = true; continue; }
            if c.is_whitespace() { continue; }
            out.push(c);
        }
        out
    } else { pat.to_string() };
    let mut p = P { src: cleaned.chars().collect(), at: 0, ngroups: 0, flags: &flags };
    let node = p.alt()?;
    if p.at != p.src.len() { return Err(value_err("unbalanced parenthesis")); }
    Ok(Regex { node, ngroups: p.ngroups, flags })
}

/// Leftmost match at or after `from`, as (start, end, groups).
fn search_at(rx: &Regex, text: &[char], from: usize) -> Option<(usize, usize, Vec<Option<(usize, usize)>>)> {
    for start in from..=text.len() {
        let mut m = M { text, flags: rx.flags, caps: vec![None; rx.ngroups + 1], steps: 0 };
        let mut end_at: Option<usize> = None;
        let hit = m.m(&rx.node, start, &mut |_me: &mut M, e: usize| { end_at = Some(e); true });
        if hit {
            let end = end_at.unwrap_or(start);
            let mut caps = m.caps.clone();
            caps[0] = Some((start, end));
            return Some((start, end, caps));
        }
    }
    None
}

fn parse_flags(v: Option<&Value>) -> R<Flags> {
    let mut f = Flags::default();
    let n = match v { None | Some(Value::None) => 0, Some(Value::Int(i)) => *i, _ => return Err(type_err("flags must be an int")) };
    f.i = n & 2 != 0;
    f.m = n & 8 != 0;
    f.s = n & 16 != 0;
    f.x = n & 64 != 0;
    Ok(f)
}

fn expand_template(tpl: &str, text: &[char], caps: &[Option<(usize, usize)>]) -> R<String> {
    let mut out = String::new();
    let mut it = tpl.chars().peekable();
    while let Some(c) = it.next() {
        if c != '\\' { out.push(c); continue; }
        match it.next() {
            Some(d) if d.is_ascii_digit() => {
                let idx = d as usize - '0' as usize;
                if let Some(Some((s0, e0))) = caps.get(idx) { out.extend(&text[*s0..*e0]); }
            }
            Some('g') => return Err(unsupported("regex", "\\g<name> template reference")),
            Some('n') => out.push('\n'),
            Some('t') => out.push('\t'),
            Some(other) => { out.push('\\'); out.push(other); }
            None => out.push('\\'),
        }
    }
    Ok(out)
}
