import subprocess, os
from concurrent.futures import ThreadPoolExecutor
LYP = os.path.expanduser("~/.lypning/bin/lypning")
CPY = "/usr/bin/python3.11"
RUN = "/tmp/t1work/run"

def one(e):
    prog = "print(repr(%s))" % e
    a = subprocess.run([LYP, "-c", prog], capture_output=True, text=True, cwd=RUN)
    b = subprocess.run([CPY, "-c", prog], capture_output=True, text=True, cwd=RUN)
    return e, a, b

def sweep(exprs, label):
    diffs=[]; refused=0; cerr=0; ok=0; rcd=[]
    with ThreadPoolExecutor(max_workers=16) as ex:
        for e,a,b in ex.map(one, exprs):
            if a.returncode == 90: refused+=1; continue
            if b.returncode != 0:
                cerr+=1
                if a.returncode==0: rcd.append((e,"cpy_err rc=%d"%b.returncode, "lyp ok: "+a.stdout.strip()))
                continue
            if a.returncode != 0:
                rcd.append((e,"lyp rc=%d"%a.returncode, a.stderr.strip().splitlines()[-1] if a.stderr.strip() else "")); continue
            if a.stdout != b.stdout: diffs.append((e,a.stdout.strip(),b.stdout.strip()))
            else: ok+=1
    print("### %s: %d exprs, ok=%d refused=%d cpy_err=%d MISMATCH=%d rcdiff=%d" % (label,len(exprs),ok,refused,cerr,len(diffs),len(rcd)))
    for e,l,c in diffs: print("  MISMATCH  %s\n     lyp: %s\n     cpy: %s"%(e,l,c))
    for e,x,y in rcd: print("  RCDIFF    %s | %s | %s"%(e,x,y))
    return diffs

