"""A/B differential: run every corpus program under the before and after
binaries in its own temp cwd, and report every row where the ANSWER changed.
Lost answers (before answered, after refuses) are the thing being hunted."""
import json, subprocess, sys, tempfile, shutil, os, concurrent.futures as cf

BEFORE = sys.argv[1]
AFTER = sys.argv[2]
CORPUS = sys.argv[3]

progs = []
seen = set()
with open(CORPUS) as fh:
    for line in fh:
        line = line.strip()
        if not line:
            continue
        e = json.loads(line)
        p = e.get("program")
        if not p or p in seen:
            continue
        seen.add(p)
        progs.append((e.get("id", "?"), p))

def one(exe, prog):
    d = tempfile.mkdtemp()
    try:
        r = subprocess.run([exe, "-c", prog], capture_output=True, text=True,
                           cwd=d, timeout=10, stdin=subprocess.DEVNULL,
                           errors="replace")
        last = (r.stderr.strip().splitlines() or [""])[-1]
        return (r.returncode, r.stdout, last)
    except subprocess.TimeoutExpired:
        return ("TIMEOUT", "", "")
    except Exception as ex:
        return ("ERR", "", str(ex))
    finally:
        shutil.rmtree(d, ignore_errors=True)

def pair(item):
    pid, prog = item
    return pid, prog, one(BEFORE, prog), one(AFTER, prog)

rows = []
with cf.ThreadPoolExecutor(max_workers=8) as ex:
    for pid, prog, b, a in ex.map(pair, progs):
        if b != a:
            rows.append((pid, prog, b, a))

print("programs: %d   changed: %d" % (len(progs), len(rows)))
lost = 0
for pid, prog, b, a in rows:
    tag = ""
    if b[0] != 90 and a[0] == 90:
        tag = "  <<< LOST ANSWER (now refuses)"
        lost += 1
    elif b[0] == 90 and a[0] != 90:
        tag = "  <<< now answered"
    elif b[1] != a[1]:
        tag = "  <<< STDOUT CHANGED"
    print("--- %s%s" % (pid, tag))
    print("    prog: %r" % (prog[:200],))
    print("    before: %r" % (b,))
    print("    after:  %r" % (a,))
print("LOST ANSWERS: %d" % lost)

