        }
        match t {
            's' | 'd' | 'f' | 'F' | 'e' | 'E' | 'g' | 'G' | 'x' | 'X' | 'o' | 'b' | 'c' | '%' => {
                sp.ty = Some(t)
            }
            'n' => return Err(unsupported("format", "locale-aware 'n' format type")),
            _ => return Err(value_err(format!("Unknown format code '{t}'"))),
        }
    }
