fn interned_class(n: &str) -> R<&'static str> {
    BUILTINS
        .iter()
        .chain(EXCEPTIONS.iter())
        .chain(MODULE_EXCEPTIONS.iter())
        .chain(EXTRA_CLASSES.iter())
        .find(|b| **b == n)
        .copied()
        .ok_or_else(|| unsupported("type", &format!("type() of a {n}")))
}

