    ref = run([sys.executable], prog)
    if (got.stdout, got.returncode) != (ref.stdout, ref.returncode):
        return ("DIFF", prog, "got=%r/%d %s" % (got.stdout, got.returncode, got.stderr.strip()[-160:]),
                "ref=%r/%d %s" % (ref.stdout, ref.returncode, ref.stderr.strip()[-160:]))
    return None
