import importlib, pkgutil, sys, os, pathlib
sys.path.insert(0, "tests"); sys.path.insert(0, "src")
LIMIT = 131072
rows = []
for p in sorted(pathlib.Path("tests").glob("test_*.py")):
    name = p.stem
    try:
        m = importlib.import_module(name)
    except Exception as e:
        print("SKIP import", name, type(e).__name__, e); continue
    best = 0; count_near = 0; count_over = 0
    def walk(o, depth=0):
        global best, count_near, count_over
        if depth > 4: return
        if isinstance(o, str):
            if len(o) > best: best = len(o)
            if len(o) > LIMIT: count_over += 1
            elif len(o) > LIMIT//2: count_near += 1
        elif isinstance(o, (list, tuple, set, frozenset)):
            for x in o: walk(x, depth+1)
        elif isinstance(o, dict):
            for k, v in o.items(): walk(k, depth+1); walk(v, depth+1)
    for attr in dir(m):
        if attr.startswith("__"): continue
        try: v = getattr(m, attr)
        except Exception: continue
        if isinstance(v, (str, list, tuple, set, frozenset, dict)): walk(v)
    rows.append((best, count_over, count_near, name))
rows.sort(reverse=True)
for best, over, near, name in rows[:25]:
    print("%9d  over=%d near=%d  %s" % (best, over, near, name))

