import re, pathlib
p = pathlib.Path('engine_d.rs')
t = p.read_text()
bad = """        if let Op::RepOne { p, f, .. } = &mut Peeked(&mut code[pc]) {
            let _ = (p, f);
        }
"""
assert bad in t
t = t.replace(bad, "")
old = """    if given & !(I | M | S | X | A | U) != 0 {
        return Err(refuse(&format!(
            "flags: unknown flag bits 0x{:x}",
            given & !(I | M | S | X | A | U | L | DEBUG)
        )));
    }
"""
new = """    if given & !(I | M | S | X | A | U) != 0 {
        return Err(refuse(&format!(
            "flags: unknown flag bits 0x{:x}",
            given & !(I | M | S | X | A | U)
        )));
    }
"""
assert old in t
t = t.replace(old, new)
p.write_text(t)
print("ok")
